# English section, vocabulary and comprehension: synonyms, antonyms, idioms,
# one-word substitution, spelling, and the reading passages (shared stimuli
# AGNIVEERVAYU-RC1, -RC2, -RC3 in stimuli.json).
SYN = "Select the word that is closest in meaning to the given word.\n\n"
ANT = "Select the word that is most nearly opposite in meaning to the given word.\n\n"
IDI = "Select the most appropriate meaning of the idiom.\n\n"
OWS = "Select the word that can replace the given phrase.\n\n"
SPL = "Select the correctly spelt word."
RC1, RC2, RC3 = "AGNIVEERVAYU-RC1", "AGNIVEERVAYU-RC2", "AGNIVEERVAYU-RC3"
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 1, "Synonyms", SYN + "Swift",
      ["Speedy", "Silent", "Steady", "Sudden"],
      "'Swift' means moving or happening fast, so 'speedy' is the closest word. 'Sudden' means unexpected, not necessarily fast."),
    S(1, 1, "Antonyms", ANT + "Inferior",
      ["Superior", "Junior", "Lower", "Weaker"],
      "'Inferior' means lower in rank or quality; 'superior' means higher. 'Lower' and 'weaker' are close in meaning, and 'junior' refers to rank or age only."),
    S(1, 2, "Idioms", IDI + "To see eye to eye",
      ["To agree fully with someone", "To stare at someone in anger", "To meet someone face to face", "To have very good eyesight"],
      "People who 'see eye to eye' share the same opinion. It is often used in the negative: 'They do not see eye to eye on the plan.'"),
    S(1, 2, "One-word substitution", OWS + "A large shed in which aircraft are kept and repaired",
      ["Hangar", "Hanger", "Arsenal", "Harbour"],
      "A 'hangar' is a building for housing aircraft. A 'hanger' (with an e) is a frame for hanging clothes, an 'arsenal' stores weapons, and a 'harbour' shelters ships."),
    S(1, 2, "Spelling", SPL,
      ["Parachute", "Parachoot", "Parashute", "Perachute"],
      "'Parachute' is spelt para-chute: the 'sh' sound is written 'ch', as in other words from French such as 'chef' and 'machine'."),
    S(1, 1, "Reading comprehension", "According to the passage, when do most bird strikes happen?",
      ["During take-off and landing", "At cruising height above the clouds", "While aircraft are parked overnight", "During night flying only"],
      "The passage says most collisions happen close to the ground, during take-off and landing, when the aircraft is low and slow.", RC1, 1),
    S(1, 2, "Reading comprehension", "Why is the grass beside the runway kept short?",
      ["Tall grass hides insects and small animals that attract birds", "Short grass helps pilots see the runway lights", "Tall grass can catch fire from engine exhaust", "Short grass is cheaper to water in summer"],
      "The passage explains that tall grass hides insects and small animals, which attract birds, so it is kept short.", RC1, 2),
    S(1, 2, "Reading comprehension", "Why, according to the passage, does no single method of bird control work for long?",
      ["Birds learn to ignore a sound or object that never changes", "The equipment breaks down in bad weather", "Local authorities do not allow it to continue", "Airfield staff do not have enough time to use it"],
      "The passage says birds soon learn to ignore a sound or a scarecrow that never changes, which is why the safest airfields keep changing their methods.", RC1, 3),
    S(1, 2, "Reading comprehension", "In the passage, the word 'chore' most nearly means",
      ["a routine task", "a serious accident", "a written report", "an expensive tool"],
      "A 'chore' is a routine, often dull task. The passage contrasts a daily duty with an occasional chore.", RC1, 4),
    S(1, 2, "Reading comprehension", "Which is the most suitable title for the passage?",
      ["Keeping Birds Away from Runways", "The Life of the Kite", "How Engines Are Repaired", "Garbage Dumps in Our Cities"],
      "The whole passage is about why bird strikes are dangerous and how airfields try to keep birds away, so 'Keeping Birds Away from Runways' fits best.", RC1, 5),

    # ---------- Practice Test 2 ----------
    S(2, 1, "Synonyms", SYN + "Fragile",
      ["Delicate", "Heavy", "Ancient", "Valuable"],
      "Something 'fragile' breaks easily, so 'delicate' is the closest meaning. A fragile thing may also be valuable, but that is not what the word means."),
    S(2, 1, "Antonyms", ANT + "Cordial",
      ["Hostile", "Warm", "Polite", "Sincere"],
      "A 'cordial' welcome is warm and friendly. 'Hostile' means unfriendly and aggressive, the opposite; 'warm' is close in meaning to cordial, and 'polite' and 'sincere' describe related good manners."),
    S(2, 2, "Idioms", IDI + "To leave no stone unturned",
      ["To try every possible way to achieve something", "To destroy everything in one's path", "To refuse to change one's opinion", "To build something with great care"],
      "To 'leave no stone unturned' is to do everything possible to find something or get a result."),
    S(2, 2, "One-word substitution", OWS + "The scientific study of the atmosphere and weather",
      ["Meteorology", "Geology", "Astrology", "Ecology"],
      "'Meteorology' is the study of the atmosphere and weather, which pilots and air traffic controllers rely on. Geology studies rocks, astrology claims to read the stars, and ecology studies living things and their surroundings."),
    S(2, 2, "Spelling", SPL,
      ["Parliament", "Parliment", "Parlament", "Parliamant"],
      "'Parliament' keeps the silent i before the a: par-lia-ment."),
    S(2, 1, "Reading comprehension", "Why were many elders doubtful about the solar panels at first?",
      ["They felt a machine that needed no fuel could not be trusted", "They thought the panels would damage the roofs", "They wanted the money spent on a new road", "They believed kerosene lamps gave better light"],
      "The passage says the elders felt that a machine which needed no fuel could not be trusted.", RC2, 1),
    S(2, 2, "Reading comprehension", "What problem did the first monsoon bring?",
      ["Cloudy days meant less power and the batteries ran low", "Heavy rain broke several panels on the school roof", "The trained women left the village for the season", "The health centre had to close for two weeks"],
      "During the first monsoon, cloudy days reduced the power and the batteries ran low by midnight.", RC2, 2),
    S(2, 2, "Reading comprehension", "How did the two trained women keep the health centre lit on cloudy evenings?",
      ["They switched off less important loads", "They bought extra kerosene for the centre", "They moved the panels to the health centre roof", "They asked families to stay home after dark"],
      "The passage says they learned to switch off the less important loads on cloudy evenings so that the health centre always had light.", RC2, 3),
    S(2, 2, "Reading comprehension", "What does the passage suggest about the elders by the end?",
      ["They changed their minds after seeing the results", "They still refused to use solar power", "They took charge of the school's evening classes", "They had always supported the council's idea"],
      "The elders who had laughed at the idea were among the first to ask for panels on their own homes, so they changed their minds.", RC2, 4),
    S(2, 2, "Reading comprehension", "In the passage, the word 'proposed' most nearly means",
      ["suggested", "refused", "completed", "repaired"],
      "To 'propose' is to put forward an idea for others to consider. The council suggested fixing the panels; the elders then had to decide.", RC2, 5),

    # ---------- Drill only ----------
    S(0, 1, "Synonyms", SYN + "Arduous",
      ["Difficult", "Ordinary", "Pleasant", "Brief"],
      "An 'arduous' task needs a lot of effort, as an arduous route march does, so 'difficult' is the closest word."),
    S(0, 1, "Antonyms", ANT + "Mobile",
      ["Stationary", "Movable", "Portable", "Active"],
      "'Mobile' means able to move. 'Stationary' means not moving; 'movable' and 'portable' are close in meaning to mobile."),
    S(0, 2, "Idioms", IDI + "To be all ears",
      ["To listen very carefully", "To hear rumours everywhere", "To refuse to listen", "To talk without stopping"],
      "If you are 'all ears', you are giving your full attention to what someone is about to say."),
    S(0, 2, "One-word substitution", OWS + "A list of the items to be discussed at a meeting",
      ["Agenda", "Minutes", "Memorandum", "Manifesto"],
      "An 'agenda' lists what a meeting will discuss. The 'minutes' record what was said afterwards, a 'memorandum' is a short note, and a 'manifesto' sets out a group's aims."),
    S(0, 2, "Reading comprehension", "What happens to a person's reaction time after about seventeen hours without sleep, according to the passage?",
      ["It slows to a level like that after an alcoholic drink", "It becomes faster for a short time", "It stays the same if the person feels alert", "It returns to normal after a cup of tea"],
      "The passage says reaction time slows to a level similar to that of someone who has had an alcoholic drink.", RC3, 1),
    S(0, 2, "Reading comprehension", "Why, according to the passage, is tiredness especially dangerous?",
      ["Tired people rarely notice their own mistakes", "Tired people always fall asleep on duty", "Tiredness spreads quickly to other crew members", "Tiredness cannot be reduced by rest"],
      "The passage says the danger is that tired people rarely notice it themselves: they feel alert while making more and more small mistakes.", RC3, 2),
    S(0, 2, "Reading comprehension", "What do round-the-clock organisations do about rest, according to the passage?",
      ["They plan it as carefully as work", "They leave it to each worker to decide", "They allow it only after a mistake", "They reduce it during busy seasons"],
      "The passage says organisations that work round the clock plan rest as carefully as they plan work.", RC3, 3),
    S(0, 1, "Reading comprehension", "What is the main idea of the passage?",
      ["Proper rest is essential for safe work", "Night shifts should be banned", "Naps make workers lazy", "Warning lights are often faulty"],
      "The passage argues that sleep is not time lost and that rest is planned for safety; its last line sums this up.", RC3, 4),
]
